@torch.jit.script
def _normalized_gate_recurrence(
    projected: torch.Tensor,
    hidden: torch.Tensor,
    weight_hh: torch.Tensor,
    bias_hh: torch.Tensor,
    reset_weight: torch.Tensor,
    reset_bias: torch.Tensor,
    update_weight: torch.Tensor,
    update_bias: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    width = hidden.size(1)
    for step in range(projected.size(1)):
        input_reset, input_update, input_new = projected[:, step].chunk(3, dim=-1)
        hidden_reset, hidden_update, hidden_new = torch.nn.functional.linear(
            hidden, weight_hh, bias_hh
        ).chunk(3, dim=-1)
        reset = torch.sigmoid(torch.nn.functional.layer_norm(
            input_reset + hidden_reset, [width], reset_weight, reset_bias, 1e-5
        ))
        update = torch.sigmoid(torch.nn.functional.layer_norm(
            input_update + hidden_update, [width], update_weight, update_bias, 1e-5
        ))
        candidate = torch.tanh(input_new + reset * hidden_new)
        hidden = (1.0 - update) * candidate + update * hidden
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


class GateNormalizedGRU(nn.GRU):
    def __init__(self, input_size: int, hidden_size: int, num_layers: int = 1,
                 batch_first: bool = True, dropout: float = 0.0):
        super().__init__(input_size, hidden_size, num_layers=num_layers,
                         batch_first=batch_first, dropout=dropout)
        self.reset_norms = nn.ModuleList([
            nn.LayerNorm(hidden_size) for _ in range(num_layers)
        ])
        self.update_norms = nn.ModuleList([
            nn.LayerNorm(hidden_size) for _ in range(num_layers)
        ])

    def forward(self, inputs: torch.Tensor, hx: torch.Tensor | None = None):
        out = inputs if self.batch_first else inputs.transpose(0, 1)
        if hx is None:
            hx = out.new_zeros(self.num_layers, out.size(0), self.hidden_size)
        final_states = []
        for layer in range(self.num_layers):
            projected = torch.nn.functional.linear(
                out, getattr(self, f'weight_ih_l{layer}'),
                getattr(self, f'bias_ih_l{layer}')
            )
            reset_norm = self.reset_norms[layer]
            update_norm = self.update_norms[layer]
